import { ObserveOptions, SkipSpansContext } from "../interfaces/observe-options.interface.js";
/** Resolved form of `ObserveOptions.skipSpans`. */
export type SkipSpansPredicate = (operation: SkipSpansContext) => boolean;
/**
 * Turns the user-facing option into the one predicate the registry asks, or
 * `undefined` when nothing is to be skipped - so an application that never
 * set it pays one falsy check per operation and builds no context object.
 *
 * A list matches on the status code alone, by strict equality: a status never
 * reaches the registry as a string, so `"404"` in the list can only be a
 * mistake, and a list that coerced its way into skipping more than it names
 * would be the worse one to get wrong.
 */
export declare function resolveSkipSpans(option: ObserveOptions["skipSpans"]): SkipSpansPredicate | undefined;
